mapper.select:
select u.LOGIN_NAME "id", u.REALNAME "name", uor.ORG_CODE "pid", 'user' as "type" from sys_user u left join SYS_USER_ORG_REL uor on u.USER_NUM = uor.USER_NUM
u.DEL_IND = '0' and uor.DEL_IND = '0'
AND u.TENANT_ID = #{tenantId}

select u.LOGIN_NAME "id", u.REALNAME "name", urr.ROLE_CODE "pid", 'user' as "type" from sys_user u left join SYS_USER_ROLE_REL urr on u.USER_NUM = urr.USER_NUM
u.DEL_IND = '0' and urr.DEL_IND = '0'
AND u.TENANT_ID = #{tenantId}

SELECT DISTINCT
su.USER_NUM,
su.REALNAME,
su.LOGIN_NAME,
sd.DEPT_NAME,
sd.DEPT_CODE,
so.ORG_CODE,
so.ORG_NAME,
sr.ROLE_CODE,
sr.ROLE_NAME
FROM
sys_user su
left join sys_user_dept_rel sud on su.USER_NUM = sud.USER_NUM and sud.DEL_IND = '0'
left join sys_user_org_rel suo on su.USER_NUM = suo.USER_NUM and suo.DEL_IND = '0'
left join sys_user_role_rel sur on su.USER_NUM = sur.USER_NUM and sur.DEL_IND = '0'
left join sys_department sd on sd.DEPT_CODE = sud.DEPT_CODE
left join sys_organization so on so.ORG_CODE = suo.ORG_CODE
left join sys_role sr on sr.ROLE_CODE = sur.ROLE_CODE


        AND su.DEL_IND = #{delInd}


        AND su.LOGIN_NAME = #{loginName}


        AND su.REALNAME = #{realname}


        AND su.USER_NUM = #{userNum}


        AND su.LOGIN_NAME IN

            #{userLoginName}




        AND su.LOGIN_NAME LIKE #{likeLoginNameLike}



        AND su.realname LIKE #{LikeRealNameLike}


        AND sd.dept_code IN

            #{deptCode}



        AND so.ORG_CODE IN

            #{orgCode}



        AND sr.ROLE_CODE IN

            #{roleCode}



        AND su.TENANT_ID = #{tenantId}

SELECT DISTINCT so.ORG_CODE, sr.ROLE_CODE, NULL "DEPT_CODE" FROM sys_user su left join sys_user_org_rel suo ON su.USER_NUM = suo.USER_NUM AND suo.DEL_IND = '0' left join sys_user_role_rel sur ON su.USER_NUM = sur.USER_NUM AND sur.DEL_IND = '0' left join sys_organization so ON so.ORG_CODE = suo.ORG_CODE left join sys_role sr ON sr.ROLE_CODE = sur.ROLE_CODE WHERE su.LOGIN_NAME = #{userId} AND so.ORG_CODE IS NOT NULL
AND su.TENANT_ID = #{tenantId}
UNION ALL SELECT DISTINCT NULL "ORG_CODE", sr.ROLE_CODE, sd.DEPT_CODE FROM sys_user su left join sys_user_dept_rel sud ON su.USER_NUM = sud.USER_NUM AND sud.DEL_IND = '0' left join sys_user_role_rel sur ON su.USER_NUM = sur.USER_NUM AND sur.DEL_IND = '0' left join sys_department sd ON sd.DEPT_CODE = sud.DEPT_CODE left join sys_role sr ON sr.ROLE_CODE = sur.ROLE_CODE WHERE su.LOGIN_NAME = #{userId} AND sd.DEPT_CODE IS NOT NULL
AND su.TENANT_ID = #{tenantId}
UNION ALL SELECT DISTINCT so.ORG_CODE, NULL "ROLE_CODE", NULL "DEPT_CODE" FROM sys_user su left join sys_user_org_rel suo ON su.USER_NUM = suo.USER_NUM AND suo.DEL_IND = '0' left join sys_organization so ON so.ORG_CODE = suo.ORG_CODE WHERE su.LOGIN_NAME = #{userId} AND so.ORG_CODE IS NOT NULL
AND su.TENANT_ID = #{tenantId}
UNION ALL SELECT DISTINCT NULL "ORG_CODE", NULL "ROLE_CODE", sd.DEPT_CODE FROM sys_user su left join sys_user_dept_rel sud ON su.USER_NUM = sud.USER_NUM AND sud.DEL_IND = '0' left join sys_department sd ON sd.DEPT_CODE = sud.DEPT_CODE WHERE su.LOGIN_NAME = #{userId} AND sd.DEPT_CODE IS NOT NULL
AND su.TENANT_ID = #{tenantId}
UNION ALL SELECT DISTINCT NULL "ORG_CODE", sr.ROLE_CODE, NULL "DEPT_CODE" FROM sys_user su left join sys_user_role_rel sur ON su.USER_NUM = sur.USER_NUM AND sur.DEL_IND = '0' left join sys_role sr ON sr.ROLE_CODE = sur.ROLE_CODE WHERE su.LOGIN_NAME = #{userId} AND sr.ROLE_CODE IS NOT NULL
AND su.TENANT_ID = #{tenantId}
UNION ALL SELECT DISTINCT so.ORG_CODE, sr.ROLE_CODE, sd.DEPT_CODE FROM sys_user su left join sys_user_org_rel suo ON su.USER_NUM = suo.USER_NUM AND suo.DEL_IND = '0' left join sys_user_role_rel sur ON su.USER_NUM = sur.USER_NUM AND sur.DEL_IND = '0' left join sys_user_dept_rel sud ON su.USER_NUM = sud.USER_NUM AND sud.DEL_IND = '0' left join sys_organization so ON so.ORG_CODE = suo.ORG_CODE left join sys_role sr ON sr.ROLE_CODE = sur.ROLE_CODE left join sys_department sd ON sd.DEPT_CODE = sud.DEPT_CODE WHERE su.LOGIN_NAME = #{userId} AND so.ORG_CODE IS NOT NULL AND sr.ROLE_CODE IS NOT NULL AND sd.DEPT_CODE IS NOT NULL
AND su.TENANT_ID = #{tenantId}

select u.LOGIN_NAME "id", u.REALNAME "name", udr.DEPT_CODE "pid", 'user' as "type" from sys_user u inner join SYS_USER_DEPT_REL udr on u.USER_NUM = udr.USER_NUM
u.DEL_IND = '0' AND udr.DEL_IND ='0'
AND u.TENANT_ID = #{tenantId}
